		"N", "S", "N", "N", "N", "S", "N", "N", // SN: N 6 / S 2
		"T", "T", "T", "F", "T", "T", "T", "T", // TF: T 7 / F 1
		"J", "J", "J", "J", "P", "J", "J", "J", // JP: J 7 / P 1
	})
