		"F", "T", "F", "F", "F", "F", "F", "F",
		"J", "J", "J", "J", "J", "J", "P", "J",
	})
	resC := &models.AssessmentResult{
		UserID: chen.ID, TypeCode: "ISFJ", Dimensions: isfjDims,
		CreatedAt: time.Now().Add(-24 * time.Hour),
	}
