		"F", "F", "F", "F", "F", "F", "T", "F", // TF: F 7 / T 1
		"P", "P", "J", "P", "P", "P", "P", "P", // JP: P 7 / J 1
	})
	resA := &models.AssessmentResult{
		UserID: lin.ID, TypeCode: "INFP", Dimensions: infpDims,
		CreatedAt: time.Now().Add(-50 * time.Hour),
	}
	DB.Create(resA)

